import java.util.concurrent.*;

/** Native dressing controls, shared server catalogue and a local GLB preview. */
public final class AvatarActivity extends Activity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private SessionStore session; private JSONObject snapshot,body,loadout;
 private LinearLayout root,list; private TextView status,wallet; private WebView preview;
 private String slot="top",rarity="",collection="";private boolean ownedOnly=false,newOnly=false,offline=false,working=false,previewHtmlLoaded=false;private int previewSeq=0;
 private static final String[] SLOTS={"body","boots","pants","gloves","top","vest","outfit","face","hair","beard","eyes","mask","head","accessory","effect","crest"};
 private static final String[] NAMES={"Corps","Chaussures","Pantalon","Gants","Maillot","Protection","Tenue complète","Visage","Cheveux","Barbe","Yeux","Masque","Couvre-chef","Accessoire","Effet","Blason"};
 private static final String[] RARITIES={"","common","rare","epic","legendary","supreme"};
 private static final String[] RARITY_NAMES={"Toutes raretés","Commun","Rare","Épique","Légendaire","Suprême"};
 private String cacheKey(){return "avatar-"+Integer.toHexString(session.token().hashCode());}
 @Override public void onCreate(Bundle b){super.onCreate(b);session=new SessionStore(this);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,28,28,42);root.setBackgroundColor(NeonPalette.BG);scroll.addView(root);setContentView(scroll);status=text("Chargement du dressing…",16);root.addView(status);refresh();}
 private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(NeonPalette.TEXT);t.setPadding(4,12,4,12);return t;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(NeonPalette.BG_DEEP);b.setPadding(18,14,18,14);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(NeonPalette.CYAN);bg.setCornerRadius(24);bg.setStroke(2,NeonPalette.CYAN_BRIGHT);b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,8,0,8);b.setLayoutParams(lp);b.setOnClickListener(v->{if(!working)action.run();});return b;}
 private void refresh(){working=true;io.execute(()->{try{JSONObject data=ApiClient.get("/api/avatar",session.token());getSharedPreferences("avatar-cache",MODE_PRIVATE).edit().putString(cacheKey(),data.toString()).apply();runOnUiThread(()->{offline=false;working=false;adopt(data);});}catch(Exception e){String cached=getSharedPreferences("avatar-cache",MODE_PRIVATE).getString(cacheKey(),"");runOnUiThread(()->{working=false;offline=true;try{if(!cached.isEmpty())adopt(new JSONObject(cached));}catch(Exception ignored){}status.setText("Hors ligne · lecture seule. "+e.getMessage());});}});}
 private void adopt(JSONObject data){snapshot=data;JSONObject p=data.optJSONObject("profile");body=p==null?new JSONObject():p.optJSONObject("body");loadout=p==null?new JSONObject():p.optJSONObject("loadout");if(body==null)body=new JSONObject();if(loadout==null)loadout=new JSONObject();render();}
 private void render(){root.removeAllViews();root.addView(button("‹ Retour au profil",this::finish));root.addView(text("MON AVATAR UNITÉ",28));root.addView(text("Personnalise ton joueur · objets et droits chargés depuis le compte",14));root.addView(button("ARMURERIE 3D · COSTUMES",()->startActivity(new android.content.Intent(this,SoldierActivity.class))));status=text(offline?"Hors ligne · lecture seule":"Inventaire chargé depuis le compte",14);root.addView(status);JSONObject coins=snapshot.optJSONObject("wallet");wallet=text(coins==null?"Monnaies indisponibles":"Points Unité "+coins.optInt("points")+" · Argent "+coins.optInt("silver")+" · Or "+coins.optInt("gold")+" · Diamants "+coins.optInt("diamonds")+"\nMonnaies de jeu, sans valeur monétaire réelle.",14);root.addView(wallet);if(snapshot.isNull("profile")){root.addView(button("CRÉER · TENUE GRATUITE",()->post("create")));return;}
 preview=new WebView(this);preview.getSettings().setJavaScriptEnabled(true);preview.getSettings().setAllowFileAccess(false);preview.getSettings().setAllowContentAccess(false);preview.setBackgroundColor(Color.TRANSPARENT);preview.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return avatarAssetResponse(request.getUrl());}});android.graphics.drawable.GradientDrawable pvbg=new android.graphics.drawable.GradientDrawable();pvbg.setColor(NeonPalette.SURFACE);pvbg.setCornerRadius(30);pvbg.setStroke(2,NeonPalette.STROKE);preview.setBackground(pvbg);LinearLayout.LayoutParams pvlp=new LinearLayout.LayoutParams(-1,680);pvlp.setMargins(0,14,0,18);root.addView(preview,pvlp);requestPreview(loadout);
 String photo=snapshot.optString("photoUrl","");if(!photo.isEmpty())root.addView(text("Votre photo personnelle reste prioritaire sur le profil.",13));
 root.addView(button("ENREGISTRER",()->post("save")));root.addView(button("RECHARGER DEPUIS LE SERVEUR",this::refresh));
 root.addView(text("Morphologie · réglages masqués jusqu’à prise en charge du modèle 3D",13));
 root.addView(text("Couleurs personnalisées · masquées jusqu’à leur rendu réel dans le modèle 3D",13));
 Spinner categories=spinner(NAMES);categories.setSelection(index(SLOTS,slot));categories.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,android.view.View v,int p,long id){slot=SLOTS[p];renderItems();}public void onNothingSelected(android.widget.AdapterView<?> a){}});root.addView(categories);
 Spinner rarities=spinner(RARITY_NAMES);rarities.setSelection(index(RARITIES,rarity));rarities.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,android.view.View v,int p,long id){rarity=RARITIES[p];renderItems();}public void onNothingSelected(android.widget.AdapterView<?> a){}});root.addView(rarities);
 JSONArray cs=snapshot.optJSONArray("collections");if(cs!=null){String[] ids=new String[cs.length()+1],names=new String[cs.length()+1];ids[0]="";names[0]="Toutes collections";for(int i=0;i<cs.length();i++){JSONObject c=cs.optJSONObject(i);ids[i+1]=c==null?"":c.optString("id");names[i+1]=c==null?"":c.optString("name");}Spinner seasons=spinner(names);seasons.setSelection(index(ids,collection));seasons.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,android.view.View v,int p,long id){collection=ids[p];renderItems();}public void onNothingSelected(android.widget.AdapterView<?> a){}});root.addView(seasons);}
 CheckBox fresh=new CheckBox(this);fresh.setText("Nouveaux objets");fresh.setTextColor(NeonPalette.TEXT);fresh.setChecked(newOnly);fresh.setOnCheckedChangeListener((b,on)->{newOnly=on;renderItems();});root.addView(fresh);
 CheckBox owned=new CheckBox(this);owned.setText("Objets possédés uniquement");owned.setTextColor(NeonPalette.TEXT);owned.setChecked(ownedOnly);owned.setOnCheckedChangeListener((b,on)->{ownedOnly=on;renderItems();});root.addView(owned);root.addView(button("RETIRER CE SLOT",()->{loadout.remove(slot);requestPreview(loadout);renderItems();}));
 list=new LinearLayout(this);list.setOrientation(1);root.addView(list);renderItems();}
 private int index(String[] a,String s){for(int i=0;i<a.length;i++)if(a[i].equals(s))return i;return 0;}
 private Spinner spinner(String[] labels){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels){@Override public android.view.View getView(int position,android.view.View convert,android.view.ViewGroup parent){TextView t=(TextView)super.getView(position,convert,parent);t.setTextColor(NeonPalette.TEXT);t.setBackgroundColor(NeonPalette.SURFACE_ALT);return t;}@Override public android.view.View getDropDownView(int position,android.view.View convert,android.view.ViewGroup parent){TextView t=(TextView)super.getDropDownView(position,convert,parent);t.setTextColor(NeonPalette.TEXT);t.setBackgroundColor(NeonPalette.SURFACE_ALT);return t;}};s.setAdapter(a);return s;}
 private boolean owns(String id){JSONArray a=snapshot.optJSONArray("inventory");if(a==null)return false;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&id.equals(o.optString("itemId"))&&(o.isNull("revokedAt")||o.optLong("revokedAt",0)==0))return true;}return false;}
 private boolean isNew(String id){JSONArray a=snapshot.optJSONArray("inventory");if(a==null)return false;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&id.equals(o.optString("itemId"))&&o.isNull("seenAt")&&o.isNull("revokedAt"))return true;}return false;}
 private void renderItems(){if(list==null)return;list.removeAllViews();JSONArray cat=snapshot.optJSONArray("catalog");if(cat==null)return;for(int i=0;i<cat.length();i++){JSONObject item=cat.optJSONObject(i);if(item==null)continue;String id=item.optString("id");if(!slot.equals(item.optString("slot"))||(!rarity.isEmpty()&&!rarity.equals(item.optString("rarity")))||(ownedOnly&&!owns(id))||(newOnly&&!isNew(id))||(!collection.isEmpty()&&!collection.equals(item.optString("collectionId")))||(!item.optBoolean("active",true)&&!owns(id)))continue;list.addView(button(item.optString("name")+" · "+(id.equals(loadout.optString(slot))?"Équipé":owns(id)?"Débloqué":"Verrouillé"),()->{
 try{JSONObject draft=new JSONObject(loadout.toString());draft.put(slot,id);if(slot.equals("outfit"))for(String part:new String[]{"boots","pants","gloves","top","vest"})draft.remove(part);else if(java.util.Arrays.asList("boots","pants","gloves","top","vest").contains(slot))draft.remove("outfit");requestPreview(draft);if(owns(id)){list.addView(button("ÉQUIPER "+item.optString("name"),()->{try{loadout.put(slot,id);if(slot.equals("outfit"))for(String part:new String[]{"boots","pants","gloves","top","vest"})loadout.remove(part);else if(java.util.Arrays.asList("boots","pants","gloves","top","vest").contains(slot))loadout.remove("outfit");renderItems();requestPreview(loadout);}catch(Exception ignored){}}),0);}else status.setText("Aperçu · déblocage : "+item.optString("unlockType")+" "+item.optString("unlockValue"));}catch(Exception e){status.setText(e.getMessage());}}));}}
 private WebResourceResponse avatarAssetResponse(Uri uri){if(uri==null||!"appassets.androidplatform.net".equals(uri.getHost()))return null;String path=uri.getPath();if(path==null||!path.equals("/assets/avatar_costumes/soldat-modulaire.glb"))return null;try{InputStream in=getAssets().open("avatar_costumes/soldat-modulaire.glb");return new WebResourceResponse("model/gltf-binary","binary",in);}catch(Exception ignored){return null;}}
 private void requestPreview(JSONObject equipped){if(preview==null||previewHtmlLoaded)return;previewHtmlLoaded=true;previewSeq++;String html="<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no'><script type='module' src='https://unpkg.com/@google/model-viewer@4.1.0/dist/model-viewer.min.js'></script><style>html,body{margin:0;width:100%;height:100%;background:#0d2029;color:#eafcff;font:15px sans-serif}body{display:flex;flex-direction:column;align-items:center;justify-content:center}model-viewer{width:100%;height:90%;background:transparent;--poster-color:transparent;touch-action:pan-y}#hint{padding:4px 12px 10px;color:#a9c5cc;text-align:center}#retry{display:none;border:1px solid #20e5f3;border-radius:18px;padding:10px 20px;background:#102a34;color:#eafcff}</style></head><body><model-viewer id='soldier' src='https://appassets.androidplatform.net/assets/avatar_costumes/soldat-modulaire.glb' alt='Soldat Unité Paintball en trois dimensions' camera-controls interaction-prompt='none' touch-action='pan-y' shadow-intensity='0.8' exposure='1.1' camera-orbit='0deg 75deg 3.5m' field-of-view='30deg'></model-viewer><div id='hint'>Aperçu du modèle 3D de base · fais glisser pour le faire tourner</div><button id='retry' onclick='location.reload()'>Réessayer l’aperçu 3D</button><script>const m=document.getElementById('soldier'),h=document.getElementById('hint'),r=document.getElementById('retry');let timer=setTimeout(fail,12000);function fail(){h.textContent='Aperçu 3D indisponible. Vérifie ta connexion et réessaie.';r.style.display='block'}m.addEventListener('load',()=>{clearTimeout(timer);h.textContent='Modèle 3D de base affiché · les pièces/couleurs équipées ne sont pas encore rendues ici.'});m.addEventListener('error',fail);</script></body></html>";preview.loadDataWithBaseURL("https://appassets.androidplatform.net/",html,"text/html","UTF-8",null);status.setText(offline?"Hors ligne · lecture seule":"Aperçu GLB du modèle de base · tenue et droits restent validés par le serveur.");}
 private void post(String action){if(offline){status.setText("Reconnectez-vous pour enregistrer.");return;}working=true;status.setText("Enregistrement…");try{JSONObject payload=new JSONObject().put("action",action).put("body",body).put("loadout",loadout).put("version",snapshot.optJSONObject("profile")==null?0:snapshot.optJSONObject("profile").optInt("version"));io.execute(()->{try{JSONObject p=ApiClient.post("/api/avatar",session.token(),payload);runOnUiThread(()->{working=false;adopt(p);status.setText("Avatar enregistré.");});}catch(Exception e){runOnUiThread(()->{working=false;status.setText(e.getMessage());});}});}catch(Exception e){working=false;status.setText(e.getMessage());}}
 @Override protected void onDestroy(){previewSeq++;if(preview!=null)preview.destroy();io.shutdownNow();super.onDestroy();}
}
